//! RECONCILIATION — the gate every derived figure has to pass through.
//!
//! Ported from `@/features/finance/lib/reconcile`. Every other capability here is arithmetic over a
//! list of transactions, and arithmetic over an INCOMPLETE list is not wrong in a way anybody can
//! see. A missing week of a statement does not produce an error; it produces a spending total that
//! is quietly too low, a runway that is quietly too long, and a payoff schedule that quietly does
//! not work. The numbers stay plausible, which is exactly what makes them dangerous.
//!
//! So reconciliation is not a report — it is a TYPE. [`reconcile`] is the only function that can
//! mint a [`ReconciledLedger`], and a capability that takes one cannot be handed transactions
//! nobody checked.
//!
//! # The brand is STRONGER here than in the TypeScript
//!
//! There it is a phantom symbol — a compile-time fiction that a cast can defeat. Here the fields are
//! private, so a struct literal outside this module is a COMPILE ERROR with no escape hatch at all.
//! The port gains something rather than approximating it.
//!
//! THERE IS NO TOLERANCE, and that is deliberate. Money is an integer count of minor units, so a
//! one-cent discrepancy has no rounding to blame — it is a real transaction that is missing,
//! doubled, or signed the wrong way. A tolerance would be a setting whose only function is to hide
//! the class of defect this module exists to find.
use crate::money::{money, subtract, sum, Currency, Money};
use crate::txn::{days_between, Txn};

/// One statement: what the institution says the account held at each end of a window.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StatementPeriod {
    pub account: String,
    /// `YYYY-MM-DD`, INCLUSIVE.
    pub from: String,
    /// `YYYY-MM-DD`, INCLUSIVE.
    pub to: String,
    pub opening: Money,
    pub closing: Money,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProblemKind {
    /// Opening + the period's transactions does not reach closing.
    Unbalanced,
    /// Consecutive statements leave days uncovered — transactions in them are simply absent.
    Gap,
    /// Two statements for one account claim the same days.
    Overlap,
    /// One statement's opening disagrees with the previous statement's closing.
    Continuity,
    /// A transaction's currency is not the period's.
    CurrencyMismatch,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Problem {
    pub kind: ProblemKind,
    pub account: String,
    /// Written for a person to act on, not for a log.
    pub detail: String,
    pub amount: Option<Money>,
    /// Transactions this problem points at — the shortlist to go and look at.
    pub suspects: Vec<Txn>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PeriodReport {
    pub account: String,
    pub from: String,
    pub to: String,
    pub balanced: bool,
    pub opening: Money,
    pub closing: Money,
    /// opening + everything dated inside the window.
    pub computed: Money,
    /// closing − computed. Zero, or the exact size of what is wrong.
    pub discrepancy: Money,
    pub counted: usize,
}

/// Transactions something has actually checked, and the date they are checked THROUGH.
///
/// EVERY FIELD IS PRIVATE. That is the enforcement: only this module can build one, so a capability
/// that asks for a `ReconciledLedger` cannot be handed a raw list by any means at all.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ReconciledLedger {
    txns: Vec<Txn>,
    through: String,
    accounts: Vec<String>,
    unverified: bool,
    caveat: Option<String>,
}

impl ReconciledLedger {
    pub fn txns(&self) -> &[Txn] {
        &self.txns
    }

    /// The last date EVERY account is covered through — see [`coverage_through`].
    pub fn through(&self) -> &str {
        &self.through
    }

    pub fn accounts(&self) -> &[String] {
        &self.accounts
    }

    /// True when this came from [`unverified_ledger`] rather than a passing reconcile.
    pub fn unverified(&self) -> bool {
        self.unverified
    }

    pub fn caveat(&self) -> Option<&str> {
        self.caveat.as_deref()
    }

    /// The transactions a derived figure may use: everything up to the date coverage actually reaches.
    pub fn covered(&self) -> Vec<Txn> {
        self.txns.iter().filter(|t| t.date <= self.through).cloned().collect()
    }

    /// A one-line statement of what a figure derived from this ledger is standing on.
    pub fn provenance(&self) -> String {
        let base = format!(
            "{} transaction(s) across {} account(s), covered through {}",
            self.txns.len(),
            self.accounts.len(),
            self.through
        );
        match &self.caveat {
            Some(c) if self.unverified => format!("UNVERIFIED — {c} · {base}"),
            _ => format!("reconciled · {base}"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct ReconcileResult {
    pub ok: bool,
    /// Present only when every period balanced and nothing is missing between them.
    pub ledger: Option<ReconciledLedger>,
    pub periods: Vec<PeriodReport>,
    pub problems: Vec<Problem>,
    /// Transactions belonging to no supplied period. Not counted, and not silently dropped either.
    pub uncovered: Vec<Txn>,
}

fn next_day(d: &str) -> String {
    match crate::session::epoch_seconds(&format!("{d}T00:00:00Z")) {
        Some(s) => crate::session::iso_from_epoch(s + 86_400)[..10].to_string(),
        None => d.to_string(),
    }
}

fn in_period(t: &Txn, p: &StatementPeriod) -> bool {
    t.account == p.account && t.date >= p.from && t.date <= p.to
}

/// The last date the WHOLE picture is trustworthy through — the EARLIEST of each account's coverage.
///
/// A ledger is only as complete as its least-covered account. Checking reconciled through August and
/// a credit card only through July does not give you an August position: August's card spending is
/// missing, so every August figure is too flattering. Taking the maximum here would be the specific
/// mistake that produces a confident, wrong number.
pub fn coverage_through(periods: &[StatementPeriod]) -> Option<String> {
    let mut last: std::collections::BTreeMap<&str, &str> = std::collections::BTreeMap::new();
    for p in periods {
        let e = last.entry(p.account.as_str()).or_insert(p.to.as_str());
        if p.to.as_str() > *e {
            *e = p.to.as_str();
        }
    }
    last.values().min().map(|s| s.to_string())
}

/// Explain a discrepancy by pointing at the transactions that would produce exactly it.
fn explain(discrepancy: i64, rows: &[Txn]) -> (String, Vec<Txn>) {
    // A SIGN ERROR IS TWICE THE AMOUNT, and it is checked FIRST. Booking −$50 as +$50 moves the
    // balance by $100, so a $100 discrepancy with a $50 transaction present is far more likely a
    // sign error than a missing $100 charge — and the two want completely different fixes.
    let halved: Vec<Txn> = rows.iter().filter(|t| t.amount.minor.abs() * 2 == discrepancy.abs()).cloned().collect();
    if !halved.is_empty() {
        let what = if halved.len() == 1 { "one transaction".to_string() } else { format!("{} transactions", halved.len()) };
        return (
            format!("the discrepancy is exactly twice {what} — a sign error, not a missing row: money leaving the account must be negative"),
            halved,
        );
    }
    let exact: Vec<Txn> = rows.iter().filter(|t| t.amount.minor.abs() == discrepancy.abs()).cloned().collect();
    if !exact.is_empty() {
        let what = if exact.len() == 1 { "one transaction".to_string() } else { format!("{} transactions", exact.len()) };
        return (
            format!("the discrepancy is exactly {what} in this period — check whether it was counted twice, or a matching one is missing"),
            exact,
        );
    }
    ("no single transaction accounts for it — the statement is probably missing rows".to_string(), Vec::new())
}

pub fn reconcile(txns: &[Txn], periods: &[StatementPeriod]) -> ReconcileResult {
    let mut problems: Vec<Problem> = Vec::new();
    let mut reports: Vec<PeriodReport> = Vec::new();
    let mut claimed: Vec<bool> = vec![false; txns.len()];

    for p in periods {
        let rows: Vec<Txn> = txns
            .iter()
            .enumerate()
            .filter(|(i, t)| {
                let hit = in_period(t, p);
                if hit {
                    claimed[*i] = true;
                }
                hit
            })
            .map(|(_, t)| t.clone())
            .collect();

        let wrong_currency: Vec<Txn> = rows.iter().filter(|t| t.amount.currency != p.opening.currency).cloned().collect();
        for t in &wrong_currency {
            problems.push(Problem {
                kind: ProblemKind::CurrencyMismatch,
                account: p.account.clone(),
                detail: format!(
                    "a {} transaction on {} sits in a {} statement — converting it is a decision, not an assumption this can make",
                    t.amount.currency, t.date, p.opening.currency
                ),
                amount: None,
                suspects: vec![t.clone()],
            });
        }

        let same: Vec<Money> = rows.iter().filter(|t| t.amount.currency == p.opening.currency).map(|t| t.amount).collect();
        let movement = sum(&same, p.opening.currency).unwrap_or(money(0, p.opening.currency));
        let computed = money(p.opening.minor + movement.minor, p.opening.currency);
        let discrepancy = subtract(p.closing, computed).unwrap_or(money(0, p.opening.currency));
        let balanced = discrepancy.minor == 0 && wrong_currency.is_empty();

        if discrepancy.minor != 0 {
            let (detail, suspects) = explain(discrepancy.minor, &rows);
            problems.push(Problem {
                kind: ProblemKind::Unbalanced,
                account: p.account.clone(),
                detail: format!("{}..{} is out by {} minor units — {detail}", p.from, p.to, discrepancy.minor),
                amount: Some(discrepancy),
                suspects,
            });
        }

        reports.push(PeriodReport {
            account: p.account.clone(),
            from: p.from.clone(),
            to: p.to.clone(),
            balanced,
            opening: p.opening,
            closing: p.closing,
            computed,
            discrepancy,
            counted: rows.len(),
        });
    }

    // BETWEEN the statements, per account: a gap, an overlap, or an opening that disagrees with the
    // previous closing. Each period can balance perfectly and the SET still be missing a month.
    let mut by_account: std::collections::BTreeMap<&str, Vec<&StatementPeriod>> = std::collections::BTreeMap::new();
    for p in periods {
        by_account.entry(p.account.as_str()).or_default().push(p);
    }
    for (account, ps) in &by_account {
        let mut sorted = ps.clone();
        sorted.sort_by(|a, b| a.from.cmp(&b.from));
        for w in sorted.windows(2) {
            let (prev, next) = (w[0], w[1]);
            if next.from <= prev.to {
                problems.push(Problem {
                    kind: ProblemKind::Overlap,
                    account: (*account).to_string(),
                    detail: format!(
                        "{}..{} overlaps {}..{} — the shared days would be counted twice",
                        next.from, next.to, prev.from, prev.to
                    ),
                    amount: None,
                    suspects: Vec::new(),
                });
                continue;
            }
            let missing = days_between(&prev.to, &next.from) - 1;
            if missing > 0 {
                problems.push(Problem {
                    kind: ProblemKind::Gap,
                    account: (*account).to_string(),
                    detail: format!(
                        "{missing} day(s) uncovered between {} and {} — anything spent in them is absent, and every total below is too low by however much that was",
                        prev.to, next.from
                    ),
                    amount: None,
                    suspects: Vec::new(),
                });
                continue;
            }
            if next.opening.minor != prev.closing.minor {
                problems.push(Problem {
                    kind: ProblemKind::Continuity,
                    account: (*account).to_string(),
                    detail: format!(
                        "{} opens at {} but {} closed at {} — consecutive statements disagree about the same moment",
                        next_day(&prev.to),
                        next.opening.minor,
                        prev.to,
                        prev.closing.minor
                    ),
                    amount: subtract(next.opening, prev.closing).ok(),
                    suspects: Vec::new(),
                });
            }
        }
    }

    let uncovered: Vec<Txn> = txns.iter().zip(&claimed).filter(|(_, c)| !**c).map(|(t, _)| t.clone()).collect();
    let ok = problems.is_empty() && uncovered.is_empty() && !periods.is_empty();
    let through = coverage_through(periods);

    let ledger = match (ok, through) {
        (true, Some(through)) => {
            let mut sorted = txns.to_vec();
            sorted.sort_by(|a, b| a.date.cmp(&b.date));
            Some(ReconciledLedger {
                txns: sorted,
                through,
                accounts: by_account.keys().map(|k| (*k).to_string()).collect(),
                unverified: false,
                caveat: None,
            })
        }
        _ => None,
    };

    ReconcileResult { ok, ledger, periods: reports, problems, uncovered }
}

/// A ledger accepted WITHOUT a reconcile, because sometimes there is no opening balance to check
/// against and a system that refuses outright is a system nobody uses.
///
/// Deliberately ugly to reach for: it demands a reason, marks the ledger `unverified`, and its name
/// is greppable — so "which of these figures rests on unchecked data?" is a question with an answer.
pub fn unverified_ledger(txns: &[Txn], through: &str, caveat: &str) -> Result<ReconciledLedger, String> {
    if caveat.trim().is_empty() {
        return Err("an unverified ledger must say why it could not be reconciled".to_string());
    }
    let mut sorted = txns.to_vec();
    sorted.sort_by(|a, b| a.date.cmp(&b.date));
    let mut accounts: Vec<String> = sorted.iter().map(|t| t.account.clone()).collect();
    accounts.sort();
    accounts.dedup();
    Ok(ReconciledLedger {
        txns: sorted,
        through: through.to_string(),
        accounts,
        unverified: true,
        caveat: Some(caveat.to_string()),
    })
}

/// A currency for a period, so a caller does not have to reach into `money` for the common case.
pub fn usd_period(account: &str, from: &str, to: &str, opening: i64, closing: i64) -> StatementPeriod {
    StatementPeriod {
        account: account.to_string(),
        from: from.to_string(),
        to: to.to_string(),
        opening: money(opening, Currency::USD),
        closing: money(closing, Currency::USD),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
    fn tx(date: &str, description: &str, minor: i64) -> Txn {
        Txn { date: date.into(), description: description.into(), amount: usd(minor), account: "checking".into() }
    }

    fn period(closing: i64) -> StatementPeriod {
        usd_period("checking", "2026-06-01", "2026-06-30", 100_000, closing)
    }

    fn rows() -> Vec<Txn> {
        vec![tx("2026-06-03", "PAY", 200_000), tx("2026-06-05", "RENT", -150_000)]
    }

    /// One row of the parity table — named rather than a tuple, so each expectation says which
    /// question it is answering.
    struct Case {
        label: &'static str,
        txns: Vec<Txn>,
        period: StatementPeriod,
        ok: bool,
        discrepancy: i64,
        kind: Option<ProblemKind>,
    }

    /// EVERY EXPECTATION HERE CAME FROM RUNNING `@/features/finance/lib/reconcile`, not from reading
    /// it — the method the money batch's four silent divergences established.
    #[test]
    fn the_port_matches_the_typescript_case_for_case() {
        let cases = vec![
            Case { label: "balanced", txns: rows(), period: period(150_000), ok: true, discrepancy: 0, kind: None },
            Case { label: "one cent", txns: rows(), period: period(150_001), ok: false, discrepancy: 1, kind: Some(ProblemKind::Unbalanced) },
            Case {
                label: "sign error",
                txns: vec![tx("2026-06-03", "PAY", 200_000), tx("2026-06-05", "RENT", 150_000)],
                period: period(150_000),
                ok: false,
                discrepancy: -300_000,
                kind: Some(ProblemKind::Unbalanced),
            },
            Case { label: "exact match", txns: rows(), period: period(350_000), ok: false, discrepancy: 200_000, kind: Some(ProblemKind::Unbalanced) },
            Case {
                label: "no explanation",
                txns: vec![tx("2026-06-03", "PAY", 200_000)],
                period: period(277_700),
                ok: false,
                discrepancy: -22_300,
                kind: Some(ProblemKind::Unbalanced),
            },
        ];
        for c in &cases {
            let r = reconcile(&c.txns, std::slice::from_ref(&c.period));
            assert_eq!(r.ok, c.ok, "{}: ok", c.label);
            assert_eq!(r.periods[0].discrepancy.minor, c.discrepancy, "{}: discrepancy", c.label);
            assert_eq!(r.problems.first().map(|x| x.kind), c.kind, "{}: problem kind", c.label);
        }
    }

    #[test]
    fn a_doubled_amount_is_a_sign_error_and_it_is_checked_first() {
        // RENT booked +1500 instead of −1500 moves the balance by 3000, not 1500. A detector that
        // matched the discrepancy against amounts directly would hunt a missing $3,000 charge that
        // does not exist — and the two want completely different fixes.
        let r = reconcile(&[tx("2026-06-03", "PAY", 200_000), tx("2026-06-05", "RENT", 150_000)], &[period(150_000)]);
        let p = r.problems.iter().find(|x| x.kind == ProblemKind::Unbalanced).unwrap();
        assert!(p.detail.contains("sign error"), "{}", p.detail);
        assert_eq!(p.suspects.iter().map(|t| t.description.as_str()).collect::<Vec<_>>(), ["RENT"]);
    }

    #[test]
    fn one_cent_is_refused_because_integers_have_no_rounding_to_blame() {
        let r = reconcile(&rows(), &[period(150_001)]);
        assert!(!r.ok);
        assert!(r.ledger.is_none());
        assert!(r.problems[0].detail.contains("missing rows"), "{}", r.problems[0].detail);
    }

    #[test]
    fn between_the_statements_matches_the_typescript_too() {
        let june = usd_period("checking", "2026-06-01", "2026-06-30", 100_000, 100_000);
        let aug = usd_period("checking", "2026-08-01", "2026-08-31", 100_000, 100_000);
        let g = reconcile(&[], &[june.clone(), aug]);
        assert_eq!(g.problems[0].kind, ProblemKind::Gap);
        assert!(g.problems[0].detail.starts_with("31 day(s) uncovered between 2026-06-30 and 2026-08-01"), "{}", g.problems[0].detail);

        let overlapping = usd_period("checking", "2026-06-15", "2026-07-15", 100_000, 100_000);
        assert_eq!(reconcile(&[], &[june.clone(), overlapping]).problems[0].kind, ProblemKind::Overlap);

        let july_disagrees = usd_period("checking", "2026-07-01", "2026-07-31", 90_000, 90_000);
        let c = reconcile(&[], &[june.clone(), july_disagrees]);
        assert_eq!(c.problems[0].kind, ProblemKind::Continuity);
        assert!(c.problems[0].detail.contains("2026-07-01 opens at 90000"), "{}", c.problems[0].detail);

        let july_abuts = usd_period("checking", "2026-07-01", "2026-07-31", 100_000, 100_000);
        let a = reconcile(&[], &[june, july_abuts]);
        assert!(a.problems.is_empty());
        assert!(a.ok);
    }

    #[test]
    fn coverage_is_the_least_covered_account_never_the_latest() {
        // Checking through August and a card only through July is not an August position: August's
        // card spending is missing, so every August figure would be too flattering.
        let ps = vec![
            usd_period("checking", "2026-08-01", "2026-08-31", 0, 0),
            usd_period("card", "2026-07-01", "2026-07-31", 0, 0),
        ];
        assert_eq!(coverage_through(&ps).as_deref(), Some("2026-07-31"));
        assert_eq!(coverage_through(&[]), None);
    }

    #[test]
    fn a_transaction_belonging_to_no_statement_is_reported_not_dropped() {
        let r = reconcile(
            &[tx("2026-06-03", "IN PERIOD", 0), tx("2026-05-03", "BEFORE ANY STATEMENT", -4_000)],
            &[period(100_000)],
        );
        assert_eq!(r.uncovered.iter().map(|t| t.description.as_str()).collect::<Vec<_>>(), ["BEFORE ANY STATEMENT"]);
        assert!(!r.ok);
        assert_eq!(r.periods[0].counted, 1);
    }

    #[test]
    fn another_accounts_rows_cannot_balance_this_one() {
        let mut card = tx("2026-06-03", "CARD SPEND", -10_000);
        card.account = "card".into();
        let r = reconcile(&[card], &[period(90_000)]);
        assert_eq!(r.periods[0].counted, 0);
        assert_eq!(r.periods[0].discrepancy.minor, -10_000);
        assert_eq!(r.uncovered.len(), 1);
    }

    #[test]
    fn a_foreign_currency_row_is_excluded_from_the_arithmetic_rather_than_added() {
        let eur = Currency::new("EUR").unwrap();
        let mut t = tx("2026-06-03", "PARIS HOTEL", -20_000);
        t.amount = money(-20_000, eur);
        let r = reconcile(&[t], &[period(100_000)]);
        assert!(!r.ok);
        let c = r.problems.iter().find(|p| p.kind == ProblemKind::CurrencyMismatch).unwrap();
        assert!(c.detail.contains("EUR"), "{}", c.detail);
        assert!(c.detail.contains("decision"), "{}", c.detail);
        // Excluded, not converted: the computed balance is untouched by it.
        assert_eq!(r.periods[0].computed.minor, 100_000);
    }

    #[test]
    fn the_ledger_is_minted_only_by_a_clean_reconcile_and_there_is_no_partial_pass() {
        assert!(reconcile(&rows(), &[period(150_000)]).ledger.is_some());
        assert!(reconcile(&rows(), &[period(150_001)]).ledger.is_none());
        // No periods at all is not a pass either.
        let empty = reconcile(&[], &[]);
        assert!(!empty.ok);
        assert!(empty.ledger.is_none());
    }

    #[test]
    fn the_unverified_hatch_demands_a_reason_and_marks_itself() {
        assert!(unverified_ledger(&[], "2026-06-30", "  ").is_err());
        let l = unverified_ledger(&rows(), "2026-06-30", "Chase export has no opening balance").unwrap();
        assert!(l.unverified());
        assert!(l.provenance().starts_with("UNVERIFIED"));
        assert!(l.provenance().contains("Chase export has no opening balance"));

        let clean = reconcile(&rows(), &[period(150_000)]).ledger.unwrap();
        assert!(clean.provenance().starts_with("reconciled"));
        assert!(clean.provenance().contains("covered through 2026-06-30"));
    }

    #[test]
    fn covered_clips_at_the_date_coverage_actually_reaches() {
        let mut card = tx("2026-07-10", "CARD SPEND", -5_000);
        card.account = "card".into();
        let l = unverified_ledger(&[card, tx("2026-06-10", "EARLY", -6_000)], "2026-06-30", "synthetic").unwrap();
        assert_eq!(l.covered().iter().map(|t| t.description.as_str()).collect::<Vec<_>>(), ["EARLY"]);
        assert_eq!(l.txns().len(), 2);
    }
}
